import "./index.scss";
const SocialLinks = () => {
  return (
    <div className="social">
      <SocialLinks.Link
        url={"https://github.com/suraj232000suman"}
        type={"github"}
      />
      <SocialLinks.Link
        url={"https://github.com/suraj232000suman"}
        type={"facebook"}
      />
      <SocialLinks.Link
        url={"https://github.com/suraj232000suman"}
        type={"send"}
      />
      <SocialLinks.Link
        url={"https://www.linkedin.com/in/surajs23"}
        // url={"https://github.com/aakash2408"}
        type={"linkedin"}
      />
    </div>
  );
};
SocialLinks.Link = ({ url, type }) => {
  return (
    <a href={url} target="_blank">
      <i className={`bi bi-${type}`}></i>
    </a>
  );
};
export default SocialLinks;
